// Deterministic approval gate. The LLM never sees this logic and cannot forge its result:
// only a user message of the exact form "APPROVE <domain>" creates an approval record.
const input = $input.first().json;
const msg = String(input.chatInput || '').trim();
const m = msg.match(/^approve\s+([a-z0-9.-]+)$/i);
const re = /^(?=.{4,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
const domain = m ? m[1].toLowerCase().replace(/\.$/, '') : null;
const isApproval = !!(domain && re.test(domain));
const now = new Date();
const TTL_MIN = 30;
return [{ json: {
  chatInput: msg,
  sessionId: input.sessionId,
  isApproval,
  approvedDomain: isApproval ? domain : null,
  domain: isApproval ? domain : null,
  status: 'granted',
  granted_at: now.toISOString(),
  expires_at: new Date(now.getTime() + TTL_MIN * 60000).toISOString(),
  session_id: String(input.sessionId || ''),
} }];
